/**
 * src/utils/aerodromeIcons.ts
 *
 * Aerodrome symbols — hand-written geometric SVGs in public/poi_icons/
 * (matching ICAO/VFR chart conventions exactly), recoloured and rasterised
 * via svgIconLoader. Same math as the original canvas-drawn versions, just
 * expressed as static SVG so both web and native can share the same source
 * asset.
 *
 * Registered image IDs (picked by @open-vfr/shared/aerodromeSymbol):
 *   ad-<kind>-<bar>  circle + main runway (kind: civ, civ-open, mil, joint,
 *                    minor; bar: hard, soft, none), generated by
 *                    scripts/gen-aerodrome-icons.mjs, own colours
 *   ad-closed        faint ring with a cross
 *   ad-heliport(-mil) purple (red) circle with white "H"
 *   ad-airport       older plain symbol (data without the symbol properties)
 *
 * Call registerAerodromeImages(map) inside a styledata event handler.
 */

import type * as maplibregl from 'maplibre-gl'
import { registerColoredSvgIcon } from './svgIconLoader'
import { AERODROME_SYMBOL_COLORS, AERODROME_SYMBOL_IDS } from '@open-vfr/shared/aerodromeSymbol'

const SZ2 = 56 // 28 logical px × 2 for HiDPI

const ICONS: [string, string, string][] = [
  ['ad-airport',      '/poi_icons/ad-airport.svg',  AERODROME_SYMBOL_COLORS.civil],
  ['ad-heliport',     '/poi_icons/ad-heliport.svg', AERODROME_SYMBOL_COLORS.heliport],
  ['ad-heliport-mil', '/poi_icons/ad-heliport.svg', AERODROME_SYMBOL_COLORS.military],
  // Colours are in the generated SVGs; the tint only fills unset parts (none).
  ...AERODROME_SYMBOL_IDS.map((id): [string, string, string] => [id, `/poi_icons/${id}.svg`, AERODROME_SYMBOL_COLORS.civil]),
]

/**
 * Fetches, recolours, and registers all aerodrome icons with the MapLibre map.
 * Safe to call multiple times — skips IDs that are already registered.
 */
export function registerAerodromeImages(map: maplibregl.Map): void {
  for (const [id, url, color] of ICONS) {
    registerColoredSvgIcon(map, id, url, color, SZ2).catch(() => { /* non-fatal */ })
  }
}
